-- Logical UTF-8 content accounting, including the new optional workflow column.
UPDATE workspace_storage_accounts SET records_bytes=records_bytes+COALESCE((SELECT SUM(length(CAST(workflow_json AS BLOB))) FROM market_monitoring_configs c WHERE c.workspace_id=workspace_storage_accounts.workspace_id),0);
