CREATE TRIGGER storage_market_monitoring_configs_insert AFTER INSERT ON market_monitoring_configs BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES(NEW.workspace_id);
 SELECT CASE WHEN EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+(COALESCE(length(CAST(NEW.frequency AS BLOB)),0)+COALESCE(length(CAST(NEW.research_depth AS BLOB)),0)+COALESCE(length(CAST(NEW.source_types_json AS BLOB)),0)+COALESCE(length(CAST(NEW.signal_ids_json AS BLOB)),0)+COALESCE(length(CAST(NEW.custom_sources_json AS BLOB)),0)+COALESCE(length(CAST(NEW.notification_channels_json AS BLOB)),0)+COALESCE(length(CAST(NEW.workflow_json AS BLOB)),0))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(COALESCE(length(CAST(NEW.frequency AS BLOB)),0)+COALESCE(length(CAST(NEW.research_depth AS BLOB)),0)+COALESCE(length(CAST(NEW.source_types_json AS BLOB)),0)+COALESCE(length(CAST(NEW.signal_ids_json AS BLOB)),0)+COALESCE(length(CAST(NEW.custom_sources_json AS BLOB)),0)+COALESCE(length(CAST(NEW.notification_channels_json AS BLOB)),0)+COALESCE(length(CAST(NEW.workflow_json AS BLOB)),0)) WHERE workspace_id=NEW.workspace_id;
END;
