CREATE TRIGGER storage_monitoring_messages_update AFTER UPDATE ON monitoring_messages BEGIN
 SELECT CASE WHEN NEW.workspace_id IS NOT OLD.workspace_id THEN RAISE(ABORT,'WORKSPACE_STORAGE_SCOPE_IMMUTABLE') END;
 SELECT CASE WHEN (COALESCE(length(CAST(NEW.template_id AS BLOB)),0)+COALESCE(length(CAST(NEW.template_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.recipient AS BLOB)),0)+COALESCE(length(CAST(NEW.subject AS BLOB)),0)+COALESCE(length(CAST(NEW.body AS BLOB)),0)+COALESCE(length(CAST(NEW.prepared_by AS BLOB)),0)+COALESCE(length(CAST(NEW.approved_by AS BLOB)),0)+COALESCE(length(CAST(NEW.connection_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.delivery_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.transport_id AS BLOB)),0)+COALESCE(length(CAST(NEW.thread_id AS BLOB)),0))>(COALESCE(length(CAST(OLD.template_id AS BLOB)),0)+COALESCE(length(CAST(OLD.template_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.recipient AS BLOB)),0)+COALESCE(length(CAST(OLD.subject AS BLOB)),0)+COALESCE(length(CAST(OLD.body AS BLOB)),0)+COALESCE(length(CAST(OLD.prepared_by AS BLOB)),0)+COALESCE(length(CAST(OLD.approved_by AS BLOB)),0)+COALESCE(length(CAST(OLD.connection_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.delivery_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.transport_id AS BLOB)),0)+COALESCE(length(CAST(OLD.thread_id AS BLOB)),0)) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+(COALESCE(length(CAST(NEW.template_id AS BLOB)),0)+COALESCE(length(CAST(NEW.template_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.recipient AS BLOB)),0)+COALESCE(length(CAST(NEW.subject AS BLOB)),0)+COALESCE(length(CAST(NEW.body AS BLOB)),0)+COALESCE(length(CAST(NEW.prepared_by AS BLOB)),0)+COALESCE(length(CAST(NEW.approved_by AS BLOB)),0)+COALESCE(length(CAST(NEW.connection_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.delivery_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.transport_id AS BLOB)),0)+COALESCE(length(CAST(NEW.thread_id AS BLOB)),0))-(COALESCE(length(CAST(OLD.template_id AS BLOB)),0)+COALESCE(length(CAST(OLD.template_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.recipient AS BLOB)),0)+COALESCE(length(CAST(OLD.subject AS BLOB)),0)+COALESCE(length(CAST(OLD.body AS BLOB)),0)+COALESCE(length(CAST(OLD.prepared_by AS BLOB)),0)+COALESCE(length(CAST(OLD.approved_by AS BLOB)),0)+COALESCE(length(CAST(OLD.connection_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.delivery_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.transport_id AS BLOB)),0)+COALESCE(length(CAST(OLD.thread_id AS BLOB)),0))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(COALESCE(length(CAST(NEW.template_id AS BLOB)),0)+COALESCE(length(CAST(NEW.template_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.recipient AS BLOB)),0)+COALESCE(length(CAST(NEW.subject AS BLOB)),0)+COALESCE(length(CAST(NEW.body AS BLOB)),0)+COALESCE(length(CAST(NEW.prepared_by AS BLOB)),0)+COALESCE(length(CAST(NEW.approved_by AS BLOB)),0)+COALESCE(length(CAST(NEW.connection_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.delivery_hash AS BLOB)),0)+COALESCE(length(CAST(NEW.transport_id AS BLOB)),0)+COALESCE(length(CAST(NEW.thread_id AS BLOB)),0))-(COALESCE(length(CAST(OLD.template_id AS BLOB)),0)+COALESCE(length(CAST(OLD.template_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.recipient AS BLOB)),0)+COALESCE(length(CAST(OLD.subject AS BLOB)),0)+COALESCE(length(CAST(OLD.body AS BLOB)),0)+COALESCE(length(CAST(OLD.prepared_by AS BLOB)),0)+COALESCE(length(CAST(OLD.approved_by AS BLOB)),0)+COALESCE(length(CAST(OLD.connection_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.delivery_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.transport_id AS BLOB)),0)+COALESCE(length(CAST(OLD.thread_id AS BLOB)),0)) WHERE workspace_id=NEW.workspace_id;
END;
CREATE TRIGGER storage_monitoring_messages_delete AFTER DELETE ON monitoring_messages BEGIN
 UPDATE workspace_storage_accounts SET records_bytes=MAX(0,records_bytes-(COALESCE(length(CAST(OLD.template_id AS BLOB)),0)+COALESCE(length(CAST(OLD.template_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.recipient AS BLOB)),0)+COALESCE(length(CAST(OLD.subject AS BLOB)),0)+COALESCE(length(CAST(OLD.body AS BLOB)),0)+COALESCE(length(CAST(OLD.prepared_by AS BLOB)),0)+COALESCE(length(CAST(OLD.approved_by AS BLOB)),0)+COALESCE(length(CAST(OLD.connection_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.delivery_hash AS BLOB)),0)+COALESCE(length(CAST(OLD.transport_id AS BLOB)),0)+COALESCE(length(CAST(OLD.thread_id AS BLOB)),0))) WHERE workspace_id=OLD.workspace_id;
END;
